import heapq

def shortest_path(edges, start, end):
    # 1. Check for negative weights
    for _, _, weight in edges:
        if weight < 0:
            raise ValueError("Negative weights are not allowed")

    # 2. Handle case where start is end
    if start == end:
        return (0, [start])

    # Build adjacency list
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        graph[u].append((v, w))

    # Initialize distances and predecessor map
    dist = {}
    prev = {}
    for u, v, w in edges:
        if u not in dist:
            dist[u] = float('inf')
            prev[u] = None
        if v not in dist:
            dist[v] = float('inf')
            prev[v] = None
    # Ensure start node is in dist
    if start not in dist:
        dist[start] = 0
        prev[start] = None
    else:
        dist[start] = 0

    # Priority queue: (distance, node)
    pq = [(0, start)]

    while pq:
        d, u = heapq.heappop(pq)

        # If we have a worse distance, skip
        if d > dist.get(u, float('inf')):
            continue

        # If we reached the end, we can stop early (optional optimization)
        if u == end:
            break

        # Explore neighbors
        if u in graph:
            for v, w in graph[u]:
                if v not in dist:
                    dist[v] = float('inf')
                    prev[v] = None

                new_dist = d + w
                if new_dist < dist.get(v, float('inf')):
                    dist[v] = new_dist
                    prev[v] = u
                    heapq.heappush(pq, (new_dist, v))

    # Check if path exists
    if dist.get(end, float('inf')) == float('inf'):
        return (None, None)

    # Reconstruct path
    path = []
    current = end
    while current is not None:
        path.append(current)
        current = prev.get(current)
    path.reverse()

    return (dist[end], path)
